idx = device.find(text="INCREASE SEARCH RADIUS")
if idx is None:
    idx = device.find(text="SEARCH RADIUS", contains=True)
if idx is None:
    raise RuntimeError("Expected 'INCREASE SEARCH RADIUS' button (failed-search state) not found; cannot widen search radius")
device.click(index=idx)

idx = device.find(text='INCREASE SEARCH RADIUS')
if idx is None:
    idx = device.find(text='SEARCH RADIUS', contains=True)
if idx is None:
    raise RuntimeError("'INCREASE SEARCH RADIUS' row not found on search screen")
device.click(idx)

idx = device.find(text='INCREASE SEARCH RADIUS')
if idx is None:
    idx = device.find(text='INCREASE SEARCH RADIUS', contains=True)
if idx is None:
    raise LookupError("'INCREASE SEARCH RADIUS' button not found on current screen")
device.click(idx)

idx = device.find(hint='Type to search all', editable=True)
if idx is None:
    idx = device.find(editable=True)
if idx is None:
    raise RuntimeError("OsmAnd favorite search field (hint 'Type to search all') not found")
device.input_text(binding['location'], index=idx)
